#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        int totalMasks = 1 << m;

        vector<vector<int>> g(m, vector<int>(m));
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                g[i][j] = gcd(nums[i], nums[j]);
            }
        }

        vector<int> dp(totalMasks, -1);
        dp[0] = 0;

        for (int mask = 0; mask < totalMasks; ++mask) {
            if (dp[mask] == -1) continue;

            int operation = __builtin_popcount(static_cast<unsigned>(mask)) / 2 + 1;

            for (int i = 0; i < m; ++i) {
                if (mask & (1 << i)) continue;

                for (int j = i + 1; j < m; ++j) {
                    if (mask & (1 << j)) continue;

                    int nextMask = mask | (1 << i) | (1 << j);
                    dp[nextMask] = max(dp[nextMask],
                                       dp[mask] + operation * g[i][j]);
                }
            }
        }

        return dp[totalMasks - 1];
    }
};

